// プレゼン教科書（ヒンディー語）第2期
// プレゼン教科書 Week 14〜20
window.PRESENT=(window.PRESENT||[]).concat([
 {week:14, level:"A1→A2", length:"1分", title:"今取り組んでいること",
  skill:"進行形（रहा हूँ・रहे हैं）を使って、今取り組んでいる仕事を1分で取引先に紹介できる。",
  lesson:[
   "第2期の始まりです。ここからプレゼンは1分になります。型は「あいさつ→今の仕事を2〜3つ→お礼」。1つの文は短くして、1文に1つのことだけを言いましょう。",
   "今週の文法は進行形です。動詞の語幹のあとに रहा（自分・男の人）・रही（女の人）・रहे（आप・हम・複数）をつけ、最後に हूँ・है・हैं を置きます。मैं हिंदी सीख रहा हूँ（ヒンディー語を学んでいます）、हम सिस्टम बना रहे हैं（システムを作っています）。日本語の「〜しています」と同じく、文の最後に来ます。",
   "「毎日〜する」という習慣は -ता हूँ、「今〜に取り組んでいる」は रहा हूँ と使い分けます。आजकल（最近）をつけると、「この頃取り組んでいること」として自然に聞こえます。ふだんの仕事は習慣形、新しい取り組みは進行形にすると、話にメリハリがつきます。",
   "取引先の前では、自分のことは मैं、チームのことは हम で話します。हम を使うと「一緒に働く仲間がいる」ことが伝わり、信頼につながります。"],
  structure:[{hi:"अभिवादन",rom:"abhivādan",ja:"あいさつ"},{hi:"परिचय",rom:"parichay",ja:"自己紹介"},{hi:"आजकल का काम",rom:"ājkal kā kām",ja:"今取り組んでいること"},{hi:"धन्यवाद",rom:"dhanyavād",ja:"お礼"}],
  phrases:[
   {hi:"नमस्ते, मैं आकिहिरो इवाता हूँ।",rom:"namaste, maiṁ Ākihiro Ivātā hūṁ.",ja:"こんにちは、岩田章弘です。",note:"最初のひとこと。名前のあとに少し間をとる。"},
   {hi:"मैं आपको अपने काम के बारे में बताता हूँ।",rom:"maiṁ āpko apne kām ke bāre meṁ batātā hūṁ.",ja:"私の仕事についてお話しします。",note:"話を始める合図。決まり文句として覚える（के बारे में＝〜について）。"},
   {hi:"मैं ओज़ू में एक्यूपंक्चर क्लिनिक चलाता हूँ।",rom:"maiṁ Ozū meṁ ekyūpankchar klinik chalātā hūṁ.",ja:"大洲で鍼灸整骨院を経営しています。",note:"ふだんの仕事は習慣形 -ता हूँ。"},
   {hi:"आजकल मैं एक नए प्रोजेक्ट पर काम कर रहा हूँ।",rom:"ājkal maiṁ ek nae projekṭ par kām kar rahā hūṁ.",ja:"最近、新しいプロジェクトに取り組んでいます。",note:"… पर काम करना で「〜に取り組む」。"},
   {hi:"हम अपने बुकिंग सिस्टम को बेहतर बना रहे हैं।",rom:"ham apne buking sisṭam ko behtar banā rahe haiṁ.",ja:"私たちは予約システムをもっと良くしているところです。",note:"チームの仕事は हम ＋ रहे हैं。"},
   {hi:"मैं दूसरे क्लिनिकों की मदद कर रहा हूँ।",rom:"maiṁ dūsre klinikoṁ kī madad kar rahā hūṁ.",ja:"ほかの院のお手伝いをしています。",note:"… की मदद करना＝〜を手伝う。"},
   {hi:"मैं भारत के होटलों के साथ काम कर रहा हूँ।",rom:"maiṁ Bhārat ke hoṭaloṁ ke sāth kām kar rahā hūṁ.",ja:"インドのホテルと一緒に仕事をしています。",note:"के साथ＝〜と一緒に。"},
   {hi:"आजकल मैं हिंदी सीख रहा हूँ।",rom:"ājkal maiṁ hindī sīkh rahā hūṁ.",ja:"最近、ヒンディー語を学んでいます。",note:"聞き手が笑顔になる一言。最後に入れると場がなごむ。"},
   {hi:"यह काम अभी चल रहा है।",rom:"yah kām abhī chal rahā hai.",ja:"この仕事は今、進んでいるところです。",note:"चल रहा है＝進行中・続いている。"},
   {hi:"सुनने के लिए धन्यवाद।",rom:"sunne ke lie dhanyavād.",ja:"聞いてくださって、ありがとうございます。",note:"締めの決まり文句として覚える。"}],
  model:{title:"今取り組んでいること", time:"1分", note:"",
   lines:[
    {hi:"नमस्ते, मैं आकिहिरो इवाता हूँ। आपका बहुत-बहुत धन्यवाद।",rom:"namaste, maiṁ Ākihiro Ivātā hūṁ. āpkā bahut-bahut dhanyavād.",ja:"こんにちは、岩田章弘です。本当にありがとうございます。"},
    {hi:"मैं आपको अपने काम के बारे में बताता हूँ।",rom:"maiṁ āpko apne kām ke bāre meṁ batātā hūṁ.",ja:"私の仕事についてお話しします。"},
    {hi:"मैं ओज़ू में एक्यूपंक्चर क्लिनिक चलाता हूँ। चार लोग मेरे साथ काम करते हैं।",rom:"maiṁ Ozū meṁ ekyūpankchar klinik chalātā hūṁ. chār log mere sāth kām karte haiṁ.",ja:"大洲で鍼灸整骨院を経営しています。4人が私と一緒に働いています。"},
    {hi:"मैं रोज़ क्लिनिक के नंबर देखता हूँ।",rom:"maiṁ roz klinik ke nambar dekhtā hūṁ.",ja:"毎日、院の数字を見ています。"},
    {hi:"आजकल हम अपने बुकिंग सिस्टम को बेहतर बना रहे हैं।",rom:"ājkal ham apne buking sisṭam ko behtar banā rahe haiṁ.",ja:"最近は、予約システムをもっと良くしているところです。"},
    {hi:"दूसरे क्लिनिक भी यह सिस्टम इस्तेमाल कर रहे हैं।",rom:"dūsre klinik bhī yah sisṭam istemāl kar rahe haiṁ.",ja:"ほかの院も、このシステムを使っています。"},
    {hi:"मैं उनकी मदद भी कर रहा हूँ।",rom:"maiṁ unkī madad bhī kar rahā hūṁ.",ja:"その院のお手伝いもしています。"},
    {hi:"भारत में मैं होटलों और रेस्टोरेंटों के साथ काम कर रहा हूँ।",rom:"Bhārat meṁ maiṁ hoṭaloṁ aur resṭorenṭoṁ ke sāth kām kar rahā hūṁ.",ja:"インドでは、ホテルやレストランと一緒に仕事をしています。"},
    {hi:"यह जापानी मेहमाननवाज़ी, यानी 'ओमोतेनाशी' का काम है।",rom:"yah jāpānī mehmānnavāzī, yānī 'omotenāshī' kā kām hai.",ja:"日本のもてなし、つまり「おもてなし」の仕事です。"},
    {hi:"और आजकल मैं हिंदी सीख रहा हूँ!",rom:"aur ājkal maiṁ hindī sīkh rahā hūṁ!",ja:"そして最近、ヒンディー語を学んでいます！"},
    {hi:"सुनने के लिए धन्यवाद।",rom:"sunne ke lie dhanyavād.",ja:"聞いてくださって、ありがとうございます。"}]},
  task:"今取り組んでいることを、進行形（रहा हूँ・रहे हैं）を3つ以上使って1分で話す。聞き手はインドの取引先。最後にお礼を言う。",
  taskEn:"In one minute, tell a business partner in India what you are working on these days. Use the Hindi progressive (rahā hūṁ / rahe haiṁ) at least three times and finish with thanks.",
  qa:[
   {q:"आजकल आप क्या कर रहे हैं?",qRom:"ājkal āp kyā kar rahe haiṁ?",a:"आजकल मैं अपने बुकिंग सिस्टम पर काम कर रहा हूँ।",aRom:"ājkal maiṁ apne buking sisṭam par kām kar rahā hūṁ.",ja:"質問：最近は何をしていますか？／答え：最近は自分の予約システムに取り組んでいます。"},
   {q:"आप हिंदी कब से सीख रहे हैं?",qRom:"āp hindī kab se sīkh rahe haiṁ?",a:"मैं कुछ महीनों से हिंदी सीख रहा हूँ।",aRom:"maiṁ kuchh mahīnoṁ se hindī sīkh rahā hūṁ.",ja:"質問：いつからヒンディー語を学んでいますか？／答え：数か月前から学んでいます。"}],
  check:["रहा・रही・रहे を主語に合わせて言えたか（自分は रहा、हम は रहे）","文の最後の हूँ・हैं を落とさなかったか","ふだんの仕事（-ता हूँ）と今の取り組み（रहा हूँ）を分けて言えたか","1分におさまったか","最後に सुनने के लिए धन्यवाद と言えたか"],
  slide:"1枚に「आजकल（最近）」と大きく書き、その下に今の取り組みを3つ、写真かアイコンで並べます。文字は短い言葉だけにします。"},

 {week:15, level:"A1→A2", length:"1分", title:"これからの計画",
  skill:"未来形（-ऊँगा・-एँगे）を使って、これからの計画を1分で取引先に伝えられる。",
  lesson:[
   "今週は「これから」を話します。計画を聞くと、相手は「この人と一緒に何ができるか」を思い浮かべられます。型は「今→これからの計画（2〜3つ）→一緒に→次の行動」です。",
   "未来形は、語幹に -ऊँगा（自分・男）、-एँगे（आप・हम）、-एगा（彼・それ）をつけます。मैं फिर भारत आऊँगा（またインドに来ます）、हम साथ में काम करेंगे（一緒に仕事をします）。करना は करूँगा・करेंगे、देना は दूँगा になります。",
   "いつの話かを文の頭で言うと、聞き手が迷いません。अगले महीने（来月）・अगले साल（来年）・एक साल बाद（1年後）を最初に置きましょう。日本語の「来年は〜します」と同じ順番です。",
   "まだ決まっていない予定には शायद（たぶん）をつけ、約束しすぎないようにします。商談では、できることだけを未来形ではっきり言い、最後に「メールをお送りします」のような次の行動で締めると、信頼につながります。"],
  structure:[{hi:"अभिवादन",rom:"abhivādan",ja:"あいさつ"},{hi:"अभी",rom:"abhī",ja:"今"},{hi:"आगे की योजना",rom:"āge kī yojnā",ja:"これからの計画"},{hi:"साथ में",rom:"sāth meṁ",ja:"一緒に"},{hi:"अगला क़दम",rom:"aglā qadam",ja:"次の行動"}],
  phrases:[
   {hi:"आज मैं अपनी आगे की योजना बताऊँगा।",rom:"āj maiṁ apnī āge kī yojnā batāūṁgā.",ja:"今日は、これからの計画をお話しします。",note:"導入で今日の話を予告する。"},
   {hi:"अगले महीने मैं फिर भारत आऊँगा।",rom:"agle mahīne maiṁ phir Bhārat āūṁgā.",ja:"来月、またインドに来ます。",note:"いつの話かを先に言う。"},
   {hi:"अगले साल हम नए क्लिनिकों के साथ काम करेंगे।",rom:"agle sāl ham nae klinikoṁ ke sāth kām kareṁge.",ja:"来年は、新しい院とも仕事をします。",note:"हम は -एँगे。करना は करेंगे。"},
   {hi:"मैं आपको हमारा सिस्टम दिखाऊँगा।",rom:"maiṁ āpko hamārā sisṭam dikhāūṁgā.",ja:"私たちのシステムをお見せします。",note:"दिखाना（見せる）→ दिखाऊँगा。"},
   {hi:"हम साथ में काम करेंगे।",rom:"ham sāth meṁ kām kareṁge.",ja:"一緒に仕事をしていきます。",note:"「一緒に」は商談でいちばん大切な言葉。"},
   {hi:"शायद हम दिल्ली में मिलेंगे।",rom:"shāyad ham Dillī meṁ mileṁge.",ja:"たぶん、デリーでお会いできます。",note:"決まっていない予定には शायद。"},
   {hi:"एक साल बाद मैं हिंदी में प्रेज़ेंटेशन दूँगा।",rom:"ek sāl bād maiṁ hindī meṁ prezenṭeshan dūṁgā.",ja:"1年後、ヒンディー語でプレゼンをします。",note:"本当の目標。देना は दूँगा になる。"},
   {hi:"इससे आपके मेहमानों को फ़ायदा होगा।",rom:"isse āpke mehmānoṁ ko fāydā hogā.",ja:"これは、お客様のためになるでしょう。",note:"होगा＝〜でしょう。言いすぎない言い方。"},
   {hi:"मैं आपको ईमेल भेजूँगा।",rom:"maiṁ āpko īmel bhejūṁgā.",ja:"メールをお送りします。",note:"次の行動を言って締めると、商談らしくなる。"},
   {hi:"भारत में फिर मिलेंगे!",rom:"Bhārat meṁ phir mileṁge!",ja:"またインドでお会いしましょう！",note:"फिर मिलेंगे は別れの決まり文句。"}],
  model:{title:"これからの計画", time:"1分", note:"計画と時期は練習用の例です。自分の予定に入れかえましょう。",
   lines:[
    {hi:"नमस्ते! आज मैं अपनी आगे की योजना बताऊँगा।",rom:"namaste! āj maiṁ apnī āge kī yojnā batāūṁgā.",ja:"こんにちは！今日は、これからの計画をお話しします。"},
    {hi:"अभी मैं ओज़ू में अपना क्लिनिक चलाता हूँ और दूसरे क्लिनिकों की मदद करता हूँ।",rom:"abhī maiṁ Ozū meṁ apnā klinik chalātā hūṁ aur dūsre klinikoṁ kī madad kartā hūṁ.",ja:"今は大洲で自分の院を経営し、ほかの院のお手伝いをしています。"},
    {hi:"पहली योजना: अगले महीने मैं फिर भारत आऊँगा।",rom:"pahlī yojnā: agle mahīne maiṁ phir Bhārat āūṁgā.",ja:"1つめの計画：来月、またインドに来ます。"},
    {hi:"मैं होटलों और रेस्टोरेंटों से मिलूँगा।",rom:"maiṁ hoṭaloṁ aur resṭorenṭoṁ se milūṁgā.",ja:"ホテルやレストランの方にお会いします。"},
    {hi:"दूसरी योजना: मैं अपना सिस्टम भारत के क्लिनिकों को दिखाऊँगा।",rom:"dūsrī yojnā: maiṁ apnā sisṭam Bhārat ke klinikoṁ ko dikhāūṁgā.",ja:"2つめの計画：私のシステムを、インドのクリニックにお見せします。"},
    {hi:"तीसरी योजना: एक साल बाद मैं हिंदी में प्रेज़ेंटेशन दूँगा।",rom:"tīsrī yojnā: ek sāl bād maiṁ hindī meṁ prezenṭeshan dūṁgā.",ja:"3つめの計画：1年後、ヒンディー語でプレゼンをします。"},
    {hi:"आज का यह छोटा प्रेज़ेंटेशन पहला क़दम है।",rom:"āj kā yah chhoṭā prezenṭeshan pahlā qadam hai.",ja:"今日のこの短いプレゼンが、最初の一歩です。"},
    {hi:"हम साथ में बहुत कुछ करेंगे।",rom:"ham sāth meṁ bahut kuchh kareṁge.",ja:"一緒に、たくさんのことをしていきましょう。"},
    {hi:"मैं अगले हफ़्ते आपको ईमेल भेजूँगा।",rom:"maiṁ agle hafte āpko īmel bhejūṁgā.",ja:"来週、メールをお送りします。"},
    {hi:"धन्यवाद! भारत में फिर मिलेंगे।",rom:"dhanyavād! Bhārat meṁ phir mileṁge.",ja:"ありがとうございました！またインドでお会いしましょう。"}]},
  task:"これからの計画を3つ、未来形を使って1分で話す。聞き手はインドの取引先。いつの話かを文の頭で言い、最後に次の行動（メールを送る など）で締める。",
  taskEn:"In one minute, tell a business partner in India about three of your plans. Use the Hindi future tense, say when at the start of each plan, and end with your next action, such as sending an email.",
  qa:[
   {q:"आप भारत कब आएँगे?",qRom:"āp Bhārat kab āeṁge?",a:"मैं अगले महीने आऊँगा। शायद दस दिन रुकूँगा।",aRom:"maiṁ agle mahīne āūṁgā. shāyad das din rukūṁgā.",ja:"質問：いつインドに来られますか？／答え：来月来ます。たぶん10日間います。"},
   {q:"आप हमें सिस्टम कब दिखाएँगे?",qRom:"āp hameṁ sisṭam kab dikhāeṁge?",a:"अगली मुलाक़ात में मैं आपको सिस्टम दिखाऊँगा।",aRom:"aglī mulāqāt meṁ maiṁ āpko sisṭam dikhāūṁgā.",ja:"質問：いつシステムを見せてくれますか？／答え：次にお会いするときにお見せします。"}],
  check:["未来形を主語に合わせて言えたか（मैं は -ऊँगा、हम・आप は -एँगे）","करूँगा・दूँगा など形の変わる動詞を正しく言えたか","いつの話かを文の頭で言えたか","決まっていない予定に शायद をつけ、約束しすぎなかったか","最後に次の行動を言って、1分におさめられたか"],
  slide:"左から右へ矢印を1本描き、「अगले महीने・अगले साल・एक साल बाद」の3つの点に計画を1つずつ置きます。"},

 {week:16, level:"A2", length:"1分30秒", title:"インドとのつながり",
  skill:"自動詞の過去形（गया・आया・पहुँचा）と था を使って、インドとのつながりを1分30秒で仲間に話せる。",
  lesson:[
   "今週の聞き手はインドの仲間です。仲間の前では、上手に話すことより、気持ちが伝わることが大切です。自分とインドとのつながりを、短い思い出として話しましょう。",
   "「行った・来た・着いた」は過去形にします。自分（男）が主語なら गया・आया・पहुँचा、आप や हम なら गए・आए・पहुँचे です。पहली बार मैं दिल्ली आया（初めてデリーに来ました）。「〜だった」は था（男・単数）・थी（女）・थे（複数・आप）で、名詞の男女に合わせます：गर्मी थी（暑かった）・ट्रैफ़िक था（渋滞だった）。",
   "思い出の話は「いつ→どこへ→どうだった→何を感じた」の順に並べると、聞き手は場面を思い浮かべやすくなります。पहली बार（初めて）・फिर（それから）・अब（今は）を話のつなぎに使いましょう。",
   "最後は感謝で締めます。आप सबका बहुत-बहुत धन्यवाद（皆さんに心から感謝します）。仲間の前のスピーチでは、勧誘や商品の話は入れず、自分の経験と感謝だけを話します。"],
  structure:[{hi:"अभिवादन",rom:"abhivādan",ja:"あいさつ"},{hi:"पहली बार",rom:"pahlī bār",ja:"初めてのインド"},{hi:"यादें",rom:"yādeṁ",ja:"思い出"},{hi:"अब",rom:"ab",ja:"今の気持ち"},{hi:"धन्यवाद",rom:"dhanyavād",ja:"感謝"}],
  phrases:[
   {hi:"नमस्ते दोस्तों!",rom:"namaste dostoṁ!",ja:"皆さん、こんにちは！",note:"仲間への呼びかけ。笑顔で、ゆっくり。"},
   {hi:"पहली बार मैं दिल्ली आया।",rom:"pahlī bār maiṁ Dillī āyā.",ja:"初めてデリーに来ました。",note:"आना（来る）の過去は आया。ने はつけない。"},
   {hi:"मैं रात को होटल पहुँचा।",rom:"maiṁ rāt ko hoṭal pahuṁchā.",ja:"夜、ホテルに着きました。",note:"पहुँचना（着く）→ पहुँचा。"},
   {hi:"बाहर बहुत गर्मी थी।",rom:"bāhar bahut garmī thī.",ja:"外はとても暑かったです。",note:"गर्मी は女の名詞なので थी。"},
   {hi:"सब लोग बहुत अच्छे थे।",rom:"sab log bahut achchhe the.",ja:"みんな、とても親切でした。",note:"人が複数なので अच्छे थे。"},
   {hi:"फिर मैं कई बार भारत आया।",rom:"phir maiṁ kaī bār Bhārat āyā.",ja:"それから何度もインドに来ました。",note:"कई बार＝何度も。"},
   {hi:"हर बार मैं ख़ुशी के साथ जापान लौटा।",rom:"har bār maiṁ khushī ke sāth Jāpān lauṭā.",ja:"毎回、うれしい気持ちで日本に帰りました。",note:"लौटना（帰る）→ लौटा。"},
   {hi:"भारत अब मेरा दूसरा घर है।",rom:"Bhārat ab merā dūsrā ghar hai.",ja:"インドは今、私の第二のふるさとです。",note:"気持ちを伝える決まり文句として覚える。"},
   {hi:"आप सब मेरे अच्छे दोस्त हैं।",rom:"āp sab mere achchhe dost haiṁ.",ja:"皆さんは、私の大切な友だちです。",note:"आप सब＝皆さん。"},
   {hi:"आप सबका बहुत-बहुत धन्यवाद।",rom:"āp sabkā bahut-bahut dhanyavād.",ja:"皆さんに、心から感謝します。",note:"仲間の前の締めの決まり文句。"}],
  model:{title:"私とインド", time:"1分30秒", note:"行った町や季節は練習用の例です。自分の思い出に入れかえましょう。",
   lines:[
    {hi:"नमस्ते दोस्तों! मैं आकिहिरो हूँ, जापान से।",rom:"namaste dostoṁ! maiṁ Ākihiro hūṁ, Jāpān se.",ja:"皆さん、こんにちは！日本から来た章弘です。"},
    {hi:"आज मैं भारत के साथ अपने रिश्ते की बात करूँगा।",rom:"āj maiṁ Bhārat ke sāth apne rishte kī bāt karūṁgā.",ja:"今日は、私とインドとのつながりについてお話しします。"},
    {hi:"पहली बार मैं दिल्ली आया। मैं रात को होटल पहुँचा।",rom:"pahlī bār maiṁ Dillī āyā. maiṁ rāt ko hoṭal pahuṁchā.",ja:"初めてデリーに来ました。夜、ホテルに着きました。"},
    {hi:"बाहर बहुत गर्मी थी और सड़क पर बहुत ट्रैफ़िक था।",rom:"bāhar bahut garmī thī aur saṛak par bahut ṭraifik thā.",ja:"外はとても暑く、道はとても混んでいました。"},
    {hi:"मुझे थोड़ा डर था।",rom:"mujhe thoṛā ḍar thā.",ja:"少し不安でした。"},
    {hi:"पर सब लोग बहुत अच्छे थे। होटल के लोग, ड्राइवर भैया, दुकानदार, सब।",rom:"par sab log bahut achchhe the. hoṭal ke log, ḍrāivar bhaiyā, dukāndār, sab.",ja:"でも、みんなとても親切でした。ホテルの人、運転手さん、お店の人、みんなです。"},
    {hi:"फिर मैं कई बार भारत आया। मैं काम के लिए आया, दोस्तों के लिए आया।",rom:"phir maiṁ kaī bār Bhārat āyā. maiṁ kām ke lie āyā, dostoṁ ke lie āyā.",ja:"それから何度もインドに来ました。仕事のために、友だちのために来ました。"},
    {hi:"पिछले महीने मैं फिर यहाँ आया, और आप सबसे मिला।",rom:"pichhle mahīne maiṁ phir yahāṁ āyā, aur āp sabse milā.",ja:"先月またここに来て、皆さんに会いました。"},
    {hi:"हर बार मैं ख़ुशी के साथ जापान लौटा।",rom:"har bār maiṁ khushī ke sāth Jāpān lauṭā.",ja:"毎回、うれしい気持ちで日本に帰りました。"},
    {hi:"भारत अब मेरा दूसरा घर है।",rom:"Bhārat ab merā dūsrā ghar hai.",ja:"インドは今、私の第二のふるさとです。"},
    {hi:"आप सब मेरे अच्छे दोस्त हैं।",rom:"āp sab mere achchhe dost haiṁ.",ja:"皆さんは、私の大切な友だちです。"},
    {hi:"आप सबका बहुत-बहुत धन्यवाद।",rom:"āp sabkā bahut-bahut dhanyavād.",ja:"皆さんに、心から感謝します。"}]},
  task:"インドとのつながりを、過去形（आया・गया・पहुँचा・था）を使って1分30秒で話す。聞き手はインドの仲間。「初めて→それから→今」の順で話し、感謝で締める。勧誘や商品の話は入れない。",
  taskEn:"In one and a half minutes, tell your friends in India about your connection with India. Use the Hindi past tense of verbs like come, go and arrive, follow the order first time, then, now, and finish with thanks. Do not include any sales talk.",
  qa:[
   {q:"आप पहली बार भारत क्यों आए?",qRom:"āp pahlī bār Bhārat kyoṁ āe?",a:"मैं काम के लिए आया। फिर भारत मुझे बहुत पसंद आया।",aRom:"maiṁ kām ke lie āyā. phir Bhārat mujhe bahut pasand āyā.",ja:"質問：初めてインドに来たのはなぜですか？／答え：仕事で来ました。それからインドがとても好きになりました。"},
   {q:"भारत में आपको सबसे अच्छा क्या लगा?",qRom:"Bhārat meṁ āpko sabse achchhā kyā lagā?",a:"यहाँ के लोग। सब लोग बहुत अच्छे थे।",aRom:"yahāṁ ke log. sab log bahut achchhe the.",ja:"質問：インドでいちばん良かったのは何ですか？／答え：ここの人たちです。みんなとても親切でした。"}],
  check:["आया・गया・पहुँचा を、自分（男）の形で言えたか（ने はつけない）","था・थी・थे を名詞の男女に合わせたか（गर्मी थी・ट्रैफ़िक था）","पहली बार・फिर・अब で話をつなげたか","1分30秒におさまったか","勧誘や商品の話を入れず、感謝で締めたか"],
  slide:"インドで撮った写真を1枚大きく入れ、下に「पहली बार → फिर → अब」の3語だけを書きます。"},

 {week:17, level:"A2", length:"1分30秒", title:"開業までの道のり",
  skill:"ने 構文（मैंने … खोला・किया）を使って、開業までの道のりを1分30秒で取引先に説明できる。",
  lesson:[
   "今週は自分の歩みを話します。取引先は「この人はどんな経験をしてきたか」を知ると、安心して仕事を任せられます。型は「昔の仕事→学んだこと→開業→今」の順です。",
   "「〜した」と言うとき、目的語をとる動詞（करना・खोलना・सीखना・बनाना など）は、主語に ने をつけます。मैंने क्लिनिक खोला（院を開きました）。このとき動詞は「私」ではなく目的語に合わせます。मैंने एक आदत बनाई（आदत は女なので बनाई）。日本語の「私が」とは考え方がちがう、と覚えましょう。",
   "ただし、先週の आया・गया（自動詞）と、था（〜だった）には ने をつけません。मैं ट्रेनर था（トレーナーでした）と मैंने काम किया（働きました）を並べて練習すると、使い分けが身につきます。",
   "年は話の中の大事な目印です。2018 は「दो हज़ार अठारह」と読みます。年を言ったら少し間をとり、聞き手が覚えられるようにしましょう。"],
  structure:[{hi:"अभिवादन",rom:"abhivādan",ja:"あいさつ"},{hi:"पहले का काम",rom:"pahle kā kām",ja:"昔の仕事"},{hi:"सीख",rom:"sīkh",ja:"学んだこと"},{hi:"क्लिनिक",rom:"klinik",ja:"開業"},{hi:"आज",rom:"āj",ja:"今"}],
  phrases:[
   {hi:"पहले मैं स्पोर्ट्स ट्रेनर था।",rom:"pahle maiṁ sporṭs ṭrenar thā.",ja:"以前は、スポーツのトレーナーでした。",note:"था には ने をつけない。"},
   {hi:"मैंने हाई स्कूल और यूनिवर्सिटी की टीमों में काम किया।",rom:"maiṁne hāī skūl aur yūnivarsiṭī kī ṭīmoṁ meṁ kām kiyā.",ja:"高校と大学のチームで働きました。",note:"काम किया（काम は男）。"},
   {hi:"मैंने प्रोफ़ेशनल टीमों के साथ भी काम किया।",rom:"maiṁne profeshanal ṭīmoṁ ke sāth bhī kām kiyā.",ja:"プロのチームとも仕事をしました。",note:"भी＝〜も。"},
   {hi:"वहाँ मैंने बहुत कुछ सीखा।",rom:"vahāṁ maiṁne bahut kuchh sīkhā.",ja:"そこで、たくさんのことを学びました。",note:"सीखना（学ぶ）→ सीखा。"},
   {hi:"मैंने जापान के नेशनल लाइसेंस लिए।",rom:"maiṁne Jāpān ke neshanal lāisens lie.",ja:"日本の国家資格をとりました。",note:"लेना → लिया。資格が複数なので लिए。"},
   {hi:"मैंने अक्टूबर 2018 में ओज़ू में अपना क्लिनिक खोला।",rom:"maiṁne akṭūbar 2018 meṁ Ozū meṁ apnā klinik kholā.",ja:"2018年10月に、大洲で自分の院を開きました。",note:"खोलना（開く）→ खोला。2018 は दो हज़ार अठारह と読む。"},
   {hi:"मैंने एक बुकिंग सिस्टम बनाया।",rom:"maiṁne ek buking sisṭam banāyā.",ja:"予約のシステムを作りました。",note:"सिस्टम は男なので बनाया。"},
   {hi:"मैंने यह सिस्टम दूसरे क्लिनिकों को भी दिया।",rom:"maiṁne yah sisṭam dūsre klinikoṁ ko bhī diyā.",ja:"このシステムを、ほかの院にも提供しました。",note:"देना → दिया。को＝〜に。"},
   {hi:"इस सफ़र में मैंने एक बात सीखी।",rom:"is safar meṁ maiṁne ek bāt sīkhī.",ja:"この道のりで、1つのことを学びました。",note:"बात は女なので सीखी。"},
   {hi:"सामने वाले इंसान के लिए पूरी कोशिश करना।",rom:"sāmne vāle insān ke lie pūrī koshish karnā.",ja:"目の前の人に全力を尽くすこと。",note:"大切にしている言葉。決まり文句として丸ごと覚える。"}],
  model:{title:"開業までの道のり", time:"1分30秒", note:"",
   lines:[
    {hi:"नमस्ते। आज मैं अपने क्लिनिक की कहानी बताऊँगा।",rom:"namaste. āj maiṁ apne klinik kī kahānī batāūṁgā.",ja:"こんにちは。今日は、私の院の物語をお話しします。"},
    {hi:"पहले मैं स्पोर्ट्स ट्रेनर था।",rom:"pahle maiṁ sporṭs ṭrenar thā.",ja:"以前は、スポーツのトレーナーでした。"},
    {hi:"मैंने हाई स्कूल, यूनिवर्सिटी, कंपनी और प्रोफ़ेशनल टीमों के साथ काम किया।",rom:"maiṁne hāī skūl, yūnivarsiṭī, kampanī aur profeshanal ṭīmoṁ ke sāth kām kiyā.",ja:"高校・大学・実業団・プロのチームと仕事をしました。"},
    {hi:"वहाँ मैंने खिलाड़ियों से बहुत कुछ सीखा।",rom:"vahāṁ maiṁne khilāṛiyoṁ se bahut kuchh sīkhā.",ja:"そこで、選手たちからたくさんのことを学びました。"},
    {hi:"फिर मैंने जापान के नेशनल लाइसेंस लिए।",rom:"phir maiṁne Jāpān ke neshanal lāisens lie.",ja:"それから、日本の国家資格をとりました。"},
    {hi:"मैं एक्यूपंक्चर और जूडो थेरेपी का काम करता हूँ।",rom:"maiṁ ekyūpankchar aur jūḍo therepī kā kām kartā hūṁ.",ja:"鍼灸と柔道整復の仕事をしています。"},
    {hi:"मैंने अक्टूबर 2018 में ओज़ू में अपना क्लिनिक खोला।",rom:"maiṁne akṭūbar 2018 meṁ Ozū meṁ apnā klinik kholā.",ja:"2018年10月に、大洲で自分の院を開きました。"},
    {hi:"अब चार लोग मेरे साथ काम करते हैं।",rom:"ab chār log mere sāth kām karte haiṁ.",ja:"今は4人が私と一緒に働いています。"},
    {hi:"क्लिनिक में मैंने एक आदत बनाई: रोज़ नंबर देखना।",rom:"klinik meṁ maiṁne ek ādat banāī: roz nambar dekhnā.",ja:"院で、1つの習慣を作りました。毎日、数字を見ることです。"},
    {hi:"बिक्री, मरीज़ों की संख्या, और दोबारा आने वाले मरीज़।",rom:"bikrī, marīzoṁ kī sankhyā, aur dobārā āne vāle marīz.",ja:"売上、来院数、そして再来院の数です。"},
    {hi:"इसी आदत से मैंने एक बुकिंग सिस्टम बनाया।",rom:"isī ādat se maiṁne ek buking sisṭam banāyā.",ja:"この習慣から、予約のシステムを作りました。"},
    {hi:"आज दूसरे क्लिनिक भी यह सिस्टम इस्तेमाल करते हैं, और मैं उनकी मदद करता हूँ।",rom:"āj dūsre klinik bhī yah sisṭam istemāl karte haiṁ, aur maiṁ unkī madad kartā hūṁ.",ja:"今はほかの院もこのシステムを使っていて、私はその院のお手伝いをしています。"},
    {hi:"इस सफ़र में मैंने एक बात सीखी: सामने वाले इंसान के लिए पूरी कोशिश करना।",rom:"is safar meṁ maiṁne ek bāt sīkhī: sāmne vāle insān ke lie pūrī koshish karnā.",ja:"この道のりで学んだことは1つです。目の前の人に全力を尽くすこと。"},
    {hi:"धन्यवाद।",rom:"dhanyavād.",ja:"ありがとうございました。"}]},
  task:"開業までの道のりを、ने 構文を4つ以上使って1分30秒で話す。聞き手はインドの取引先。「昔の仕事→学んだこと→開業→今」の順にし、最後に大切にしている言葉で締める。",
  taskEn:"In one and a half minutes, tell a business partner in India how you came to open your clinic. Use the ne construction at least four times, follow the order past job, what you learned, opening, today, and end with the value you hold most dear.",
  qa:[
   {q:"आपने क्लिनिक कब खोला?",qRom:"āpne klinik kab kholā?",a:"मैंने अक्टूबर 2018 में क्लिनिक खोला।",aRom:"maiṁne akṭūbar 2018 meṁ klinik kholā.",ja:"質問：院はいつ開きましたか？／答え：2018年10月に開きました。"},
   {q:"क्लिनिक से पहले आपने क्या किया?",qRom:"klinik se pahle āpne kyā kiyā?",a:"मैं स्पोर्ट्स ट्रेनर था। मैंने कई टीमों के साथ काम किया।",aRom:"maiṁ sporṭs ṭrenar thā. maiṁne kaī ṭīmoṁ ke sāth kām kiyā.",ja:"質問：院を開く前は何をしていましたか？／答え：スポーツのトレーナーでした。いろいろなチームと仕事をしました。"}],
  check:["目的語をとる動詞の過去に ने をつけたか（मैंने）","動詞を目的語に合わせたか（आदत बनाई・बात सीखी・सिस्टम बनाया）","था（〜だった）には ने をつけなかったか","2018 を दो हज़ार अठारह と読めたか","1分30秒におさまり、大切にしている言葉で締めたか"],
  slide:"左から右へ「ट्रेनर → लाइसेंस → 2018 क्लिनिक → सिस्टम」の4つの箱を並べた年表を1枚にします。"},

 {week:18, level:"A2", length:"1分30秒", title:"日本の食と日本酒を紹介する",
  skill:"味の言葉と「〜だった（अच्छा लगा）」を使って、日本の食と家族の酒店の日本酒を1分30秒で紹介できる。お酒を飲まない人にも配慮した言い方ができる。",
  lesson:[
   "今週は日本の食と日本酒を紹介します。岩田さんは、家族の事業である小谷酒店（1957年創業）で国際担当をしています。お店の紹介は「1957年から続いている」「自分は国際担当」という事実だけにし、受賞や売上などは話しません。",
   "味の言葉を使うと、聞き手は食べ物を思い浮かべられます。मीठा（甘い）・हल्का（軽い）・ताज़ा（新鮮な）・स्वादिष्ट（おいしい）。形容詞は名詞の男女に合わせて मीठी・हल्की のように変わります（स्वादिष्ट は変わりません）。",
   "インドではお酒を飲まない方がたくさんいます。宗教や家庭の考え、健康の理由などさまざまです。日本酒の話をするときは、「飲まない方もまったく問題ありません」と一言入れ、食べ物や文化の話を中心にしましょう。お酒をすすめる言い方（もっと飲んで、など）は使いません。",
   "感想は過去形の लगा で言います。मुझे दाल बहुत अच्छी लगी（ダールがとてもおいしかった）。相手の国の食べ物を先にほめてから日本の話をすると、話が温かく始まります。"],
  structure:[{hi:"अभिवादन",rom:"abhivādan",ja:"あいさつ（相手の国の食べ物をほめる）"},{hi:"जापानी खाना",rom:"jāpānī khānā",ja:"日本の食"},{hi:"परिवार की दुकान",rom:"parivār kī dukān",ja:"家族の酒店"},{hi:"साके",rom:"sāke",ja:"日本酒"},{hi:"सबके लिए",rom:"sabke lie",ja:"飲まない方への一言・お誘い"}],
  phrases:[
   {hi:"भारत में मुझे दाल बहुत अच्छी लगी।",rom:"Bhārat meṁ mujhe dāl bahut achchhī lagī.",ja:"インドでは、ダールがとてもおいしかったです。",note:"相手の国の食べ物を先にほめる。दाल は女なので अच्छी लगी。"},
   {hi:"आज मैं जापानी खाने के बारे में बताऊँगा।",rom:"āj maiṁ jāpānī khāne ke bāre meṁ batāūṁgā.",ja:"今日は、日本の食についてお話しします。",note:"के बारे में＝〜について。"},
   {hi:"जापानी खाना हल्का और ताज़ा है।",rom:"jāpānī khānā halkā aur tāzā hai.",ja:"日本の食事は、軽くて新鮮です。",note:"खाना は男なので हल्का。"},
   {hi:"मेरे परिवार की एक साके की दुकान है।",rom:"mere parivār kī ek sāke kī dukān hai.",ja:"私の家族は、日本酒のお店をしています。",note:"दुकान は女なので की。"},
   {hi:"वह 1957 से चल रही है।",rom:"vah 1957 se chal rahī hai.",ja:"お店は1957年から続いています。",note:"進行形で「続いている」。1957 は उन्नीस सौ सत्तावन と読む。"},
   {hi:"मैं वहाँ इंटरनेशनल काम देखता हूँ।",rom:"maiṁ vahāṁ inṭarneshanal kām dekhtā hūṁ.",ja:"私はそこで国際担当をしています。",note:"काम देखना＝担当する。"},
   {hi:"साके, यानी जापान की चावल की शराब।",rom:"sāke, yānī Jāpān kī chāval kī sharāb.",ja:"サケ、つまり日本のお米のお酒です。",note:"यानी＝つまり。知らない言葉を説明するときに便利。"},
   {hi:"यह साके थोड़ी मीठी और हल्की है।",rom:"yah sāke thoṛī mīṭhī aur halkī hai.",ja:"この日本酒は、少し甘くて軽いです。",note:"साके を女の名詞として形容詞を合わせる。"},
   {hi:"कई लोग शराब नहीं पीते। यह बिल्कुल ठीक है।",rom:"kaī log sharāb nahīṁ pīte. yah bilkul ṭhīk hai.",ja:"お酒を飲まない方もたくさんいます。それでまったく問題ありません。",note:"飲まない方への配慮の一言。日本酒の話では必ず入れる。"},
   {hi:"आप चाय या जूस के साथ भी जापानी खाना खा सकते हैं।",rom:"āp chāy yā jūs ke sāth bhī jāpānī khānā khā sakte haiṁ.",ja:"お茶やジュースと一緒でも、日本の食事を楽しめます。",note:"お酒なしでも楽しめることを伝える。"}],
  model:{title:"日本の食と、家族の酒店", time:"1分30秒", note:"お店の紹介は事実（1957年から続く酒店・自分は国際担当）だけにしています。味の感想は自分の言葉に入れかえましょう。",
   lines:[
    {hi:"नमस्ते! पिछली बार दिल्ली में मुझे दाल मखनी बहुत अच्छी लगी।",rom:"namaste! pichhlī bār Dillī meṁ mujhe dāl makhnī bahut achchhī lagī.",ja:"こんにちは！前回デリーで食べたダール・マッカニーが、とてもおいしかったです。"},
    {hi:"आज मैं जापानी खाने और साके के बारे में बताऊँगा।",rom:"āj maiṁ jāpānī khāne aur sāke ke bāre meṁ batāūṁgā.",ja:"今日は、日本の食と日本酒についてお話しします。"},
    {hi:"जापानी खाना हल्का और ताज़ा है। उसमें मसाला कम है।",rom:"jāpānī khānā halkā aur tāzā hai. usmeṁ masālā kam hai.",ja:"日本の食事は、軽くて新鮮です。スパイスは少なめです。"},
    {hi:"हम चावल, मछली, सब्ज़ी और सोया सॉस बहुत खाते हैं।",rom:"ham chāval, machhlī, sabzī aur soyā sos bahut khāte haiṁ.",ja:"私たちは、ご飯・魚・野菜・しょうゆをよく食べます。"},
    {hi:"मेरे परिवार की एक साके की दुकान है। उसका नाम ओदानी साके तेन है।",rom:"mere parivār kī ek sāke kī dukān hai. uskā nām Odānī Sāke Ten hai.",ja:"私の家族は日本酒のお店をしています。名前は小谷酒店です。"},
    {hi:"वह 1957 से चल रही है, और मैं वहाँ इंटरनेशनल काम देखता हूँ।",rom:"vah 1957 se chal rahī hai, aur maiṁ vahāṁ inṭarneshanal kām dekhtā hūṁ.",ja:"1957年から続いていて、私はそこで国際担当をしています。"},
    {hi:"साके, यानी जापान की चावल की शराब। यह चावल और पानी से बनती है।",rom:"sāke, yānī Jāpān kī chāval kī sharāb. yah chāval aur pānī se bantī hai.",ja:"サケとは、日本のお米のお酒です。お米と水から作られます。"},
    {hi:"कुछ साके मीठी हैं, कुछ हल्की हैं।",rom:"kuchh sāke mīṭhī haiṁ, kuchh halkī haiṁ.",ja:"甘い日本酒もあれば、軽い日本酒もあります。"},
    {hi:"जापानी खाने के साथ साके बहुत अच्छी लगती है।",rom:"jāpānī khāne ke sāth sāke bahut achchhī lagtī hai.",ja:"日本の食事には、日本酒がよく合います。"},
    {hi:"पर कई लोग शराब नहीं पीते। यह बिल्कुल ठीक है।",rom:"par kaī log sharāb nahīṁ pīte. yah bilkul ṭhīk hai.",ja:"でも、お酒を飲まない方もたくさんいます。それでまったく問題ありません。"},
    {hi:"आप चाय या जूस के साथ भी जापानी खाना खा सकते हैं।",rom:"āp chāy yā jūs ke sāth bhī jāpānī khānā khā sakte haiṁ.",ja:"お茶やジュースと一緒でも、日本の食事を楽しめます。"},
    {hi:"जापान आइए, साथ में खाना खाएँगे!",rom:"Jāpān āie, sāth meṁ khānā khāeṁge!",ja:"日本にいらしてください。一緒にご飯を食べましょう！"},
    {hi:"धन्यवाद।",rom:"dhanyavād.",ja:"ありがとうございました。"}]},
  task:"日本の食と家族の酒店（小谷酒店・1957年から・自分は国際担当）を1分30秒で紹介する。聞き手はインドの取引先。最初に相手の国の食べ物をほめ、お酒を飲まない方への一言を必ず入れる。お酒をすすめる言い方はしない。",
  taskEn:"In one and a half minutes, introduce Japanese food and your family's sake shop, Odani Sake Ten (in business since 1957, where you handle international work), to a business partner in India. Start by praising Indian food, include a kind line for people who do not drink alcohol, and never push anyone to drink.",
  qa:[
   {q:"आपकी दुकान कब से है?",qRom:"āpkī dukān kab se hai?",a:"हमारी दुकान 1957 से चल रही है।",aRom:"hamārī dukān 1957 se chal rahī hai.",ja:"質問：お店はいつからありますか？／答え：1957年から続いています。"},
   {q:"मैं शराब नहीं पीता।",qRom:"maiṁ sharāb nahīṁ pītā.",a:"कोई बात नहीं! हम चाय के साथ जापानी खाना खाएँगे।",aRom:"koī bāt nahīṁ! ham chāy ke sāth jāpānī khānā khāeṁge.",ja:"相手のひとこと：私はお酒を飲みません。／答え：大丈夫です！お茶と一緒に日本の食事を楽しみましょう。"}],
  check:["味の言葉を名詞の男女に合わせたか（हल्का खाना・मीठी साके）","お店の話を事実（1957年から・国際担当）だけにしたか","お酒を飲まない方への一言を入れ、すすめる言い方をしなかったか","最初に相手の国の食べ物をほめたか","1分30秒におさまったか"],
  slide:"左に日本の食事の写真、右にお店の外観の写真を置きます。下に「1957 से」と「चाय के साथ भी」の2つだけを小さく書きます。"},

 {week:19, level:"A2", length:"1分30秒", title:"おもてなしの考え方",
  skill:"習慣の現在形（-ते हैं）と未来形を使って、日本のおもてなしの考え方を1分30秒でホテルやレストランの方に説明できる。",
  lesson:[
   "今週は、岩田さんのコンサルの中心である「おもてなし」を話します。聞き手はインドのホテル・レストラン・クリニックの方です。大事なのは「日本のほうが上」と聞こえないこと。インドにもすばらしいもてなしの心があります。",
   "インドには「お客様は神さまのような存在」という考えがあります。भारत में मेहमान भगवान जैसा होता है（होता है は第23週の形。ここでは決まり文句として覚えます）。この言葉で相手の文化をたたえてから日本のおもてなしを紹介すると、話がぐっと近くなります。",
   "おもてなしは、具体的な行動で説明すると伝わります。お客様が言う前に気づく、名前を覚える、ドアまで見送る。「いつもしていること」なので、習慣の現在形 -ते हैं を使います：हम दरवाज़े तक मेहमान के साथ जाते हैं（ドアまでお見送りします）。",
   "最後は「一緒に」で締めます。हम साथ में सीखेंगे（一緒に学びましょう）。教える立場ではなく、ともに学ぶ立場で話すと、取引先との関係が長続きします。成果を約束する言い方は避けます。"],
  structure:[{hi:"अभिवादन",rom:"abhivādan",ja:"あいさつ"},{hi:"भारत की मेहमाननवाज़ी",rom:"Bhārat kī mehmānnavāzī",ja:"インドのもてなしをたたえる"},{hi:"ओमोतेनाशी",rom:"omotenāshī",ja:"日本のおもてなし"},{hi:"तीन बातें",rom:"tīn bāteṁ",ja:"3つの行動"},{hi:"साथ में",rom:"sāth meṁ",ja:"一緒に"}],
  phrases:[
   {hi:"भारत में मेहमान भगवान जैसा होता है।",rom:"Bhārat meṁ mehmān bhagvān jaisā hotā hai.",ja:"インドでは、お客様は神さまのような存在です。",note:"決まり文句として覚える。相手の文化をたたえる一言。"},
   {hi:"जापान में इसे 'ओमोतेनाशी' कहते हैं।",rom:"Jāpān meṁ ise 'omotenāshī' kahte haiṁ.",ja:"日本では、これを「おもてなし」と言います。",note:"इसे … कहते हैं＝これを〜と言います。"},
   {hi:"मेहमान कुछ नहीं कहते, पर हम देखते हैं और समझते हैं।",rom:"mehmān kuchh nahīṁ kahte, par ham dekhte haiṁ aur samajhte haiṁ.",ja:"お客様が何も言わなくても、私たちは見て、気づきます。",note:"おもてなしの1つめの行動。"},
   {hi:"छोटी-छोटी बातें बहुत ज़रूरी हैं।",rom:"chhoṭī-chhoṭī bāteṁ bahut zarūrī haiṁ.",ja:"小さなことが、とても大切です。",note:"छोटी-छोटी と重ねると「一つひとつの小さな」。"},
   {hi:"हम मेहमान का नाम याद रखते हैं।",rom:"ham mehmān kā nām yād rakhte haiṁ.",ja:"お客様のお名前を覚えておきます。",note:"याद रखना＝覚えておく。"},
   {hi:"हम दरवाज़े तक मेहमान के साथ जाते हैं।",rom:"ham darvāze tak mehmān ke sāth jāte haiṁ.",ja:"ドアまでお客様をお見送りします。",note:"तक＝〜まで。"},
   {hi:"हमारा मक़सद एक है: मेहमान की ख़ुशी।",rom:"hamārā maqsad ek hai: mehmān kī khushī.",ja:"目的は1つ、お客様の喜びです。",note:"話の芯になる一文。ゆっくり言う。"},
   {hi:"जापानी मेहमान आपके होटल में आएँगे।",rom:"jāpānī mehmān āpke hoṭal meṁ āeṁge.",ja:"日本のお客様が、あなたのホテルに来られます。",note:"मेहमान は複数なので आएँगे。"},
   {hi:"मैं आपकी टीम के साथ काम करूँगा।",rom:"maiṁ āpkī ṭīm ke sāth kām karūṁgā.",ja:"あなたのチームと一緒に仕事をします。",note:"「教える」より「一緒に」。"},
   {hi:"हम साथ में सीखेंगे।",rom:"ham sāth meṁ sīkheṁge.",ja:"一緒に学んでいきましょう。",note:"ともに学ぶ立場で締める。"}],
  model:{title:"おもてなしの考え方", time:"1分30秒", note:"",
   lines:[
    {hi:"नमस्ते। समय देने के लिए धन्यवाद।",rom:"namaste. samay dene ke lie dhanyavād.",ja:"こんにちは。お時間をいただき、ありがとうございます。"},
    {hi:"भारत में मेहमान भगवान जैसा होता है। यह बहुत सुंदर सोच है।",rom:"Bhārat meṁ mehmān bhagvān jaisā hotā hai. yah bahut sundar soch hai.",ja:"インドでは、お客様は神さまのような存在です。とてもすてきな考え方です。"},
    {hi:"जापान में भी ऐसी एक सोच है। उसे 'ओमोतेनाशी' कहते हैं।",rom:"Jāpān meṁ bhī aisī ek soch hai. use 'omotenāshī' kahte haiṁ.",ja:"日本にも同じような考え方があります。それを「おもてなし」と言います。"},
    {hi:"ओमोतेनाशी में तीन बातें ज़रूरी हैं।",rom:"omotenāshī meṁ tīn bāteṁ zarūrī haiṁ.",ja:"おもてなしでは、3つのことが大切です。"},
    {hi:"पहली बात: मेहमान कुछ नहीं कहते, पर हम देखते हैं और समझते हैं।",rom:"pahlī bāt: mehmān kuchh nahīṁ kahte, par ham dekhte haiṁ aur samajhte haiṁ.",ja:"1つめ：お客様が何も言わなくても、私たちは見て、気づきます。"},
    {hi:"दूसरी बात: छोटी-छोटी बातें। हम मेहमान का नाम याद रखते हैं।",rom:"dūsrī bāt: chhoṭī-chhoṭī bāteṁ. ham mehmān kā nām yād rakhte haiṁ.",ja:"2つめ：小さなことです。お客様のお名前を覚えておきます。"},
    {hi:"तीसरी बात: हम आख़िर तक ध्यान रखते हैं। हम दरवाज़े तक मेहमान के साथ जाते हैं।",rom:"tīsrī bāt: ham ākhir tak dhyān rakhte haiṁ. ham darvāze tak mehmān ke sāth jāte haiṁ.",ja:"3つめ：最後まで心を配ります。ドアまでお客様をお見送りします。"},
    {hi:"मैं होटलों, रेस्टोरेंटों और क्लिनिकों के साथ यह काम करता हूँ।",rom:"maiṁ hoṭaloṁ, resṭorenṭoṁ aur klinikoṁ ke sāth yah kām kartā hūṁ.",ja:"私は、ホテル・レストラン・クリニックと一緒にこの仕事をしています。"},
    {hi:"जापानी मेहमान, और जापान पसंद करने वाले भारतीय मेहमान, आपके पास आएँगे।",rom:"jāpānī mehmān, aur Jāpān pasand karne vāle bhāratīy mehmān, āpke pās āeṁge.",ja:"日本のお客様、そして日本が好きなインドのお客様が、あなたのところに来られます。"},
    {hi:"हमारा मक़सद एक है: मेहमान की ख़ुशी।",rom:"hamārā maqsad ek hai: mehmān kī khushī.",ja:"目的は1つ、お客様の喜びです。"},
    {hi:"मैं आपकी टीम के साथ काम करूँगा, और हम साथ में सीखेंगे।",rom:"maiṁ āpkī ṭīm ke sāth kām karūṁgā, aur ham sāth meṁ sīkheṁge.",ja:"あなたのチームと一緒に仕事をして、一緒に学んでいきます。"},
    {hi:"धन्यवाद।",rom:"dhanyavād.",ja:"ありがとうございました。"}]},
  task:"日本のおもてなしの考え方を、具体的な行動3つで1分30秒で説明する。聞き手はインドのホテルやレストランの方。最初にインドのもてなしの心をたたえ、最後は「一緒に学ぶ」で締める。",
  taskEn:"In one and a half minutes, explain the Japanese idea of omotenashi to a hotel or restaurant team in India using three concrete actions. Begin by praising Indian hospitality and finish by saying you will learn together.",
  qa:[
   {q:"ओमोतेनाशी का मतलब क्या है?",qRom:"omotenāshī kā matlab kyā hai?",a:"मेहमान के लिए दिल से सेवा। छोटी-छोटी बातों का ध्यान।",aRom:"mehmān ke lie dil se sevā. chhoṭī-chhoṭī bātoṁ kā dhyān.",ja:"質問：おもてなしとはどういう意味ですか？／答え：お客様のための心からのサービスです。小さなことへの心配りです。"},
   {q:"क्या यह भारत में भी चलेगा?",qRom:"kyā yah Bhārat meṁ bhī chalegā?",a:"हाँ। भारत में भी मेहमान भगवान जैसा है। हमारी सोच एक जैसी है।",aRom:"hāṁ. Bhārat meṁ bhī mehmān bhagvān jaisā hai. hamārī soch ek jaisī hai.",ja:"質問：それはインドでも通用しますか？／答え：はい。インドでも、お客様は神さまのような存在です。私たちの考え方は同じです。"}],
  check:["最初にインドのもてなしの心をたたえたか","3つの行動を習慣の現在形 -ते हैं で言えたか","「日本のほうが上」と聞こえる言い方をしなかったか","成果を約束せず「一緒に学ぶ」で締めたか","1分30秒におさまったか"],
  slide:"「ओमोतेनाशी」と大きく書き、その下に3つの行動（देखना・नाम・दरवाज़े तक）をアイコンと1語ずつで並べます。"},

 {week:20, level:"A2", length:"1分30秒", title:"段取りを順に説明する",
  skill:"-कर（〜してから）と順番の言葉を使って、仕事の段取りを商談の冒頭で1分30秒で説明できる。",
  lesson:[
   "今週は、商談の冒頭で「どう進めるか」を説明します。段取りがはっきりすると、相手は安心して話を聞けます。細かい条件や料金は英語で話してよいので、ヒンディー語では流れだけを示しましょう。",
   "-कर は「〜してから」の意味です。動詞の語幹に कर をつけます：देखकर（見てから）、मिलकर（会って・一緒に）、आकर（来てから）。करना だけは करके になります。2つの動作を1文でつなげられるので、段取りの説明にぴったりです。日本語の「〜して、〜します」と同じ順番です。",
   "順番の言葉を文の頭に置きます。पहले（まず）・फिर（それから）・उसके बाद（そのあと）・आख़िर में（最後に）。最初に「段階は4つです」と数を言い、指で1、2、3、4と数えながら話すと、聞き手もついてきやすくなります。",
   "最後に「この流れでよろしいですか」と相手に聞いてから本題に入ります。क्या यह ठीक है?（これでよろしいですか）。英語に切り替えるときは、अब मैं इंग्लिश में बात करूँगा（ここからは英語で話します）と一言ことわります。"],
  structure:[{hi:"अभिवादन",rom:"abhivādan",ja:"あいさつ"},{hi:"चार क़दम",rom:"chār qadam",ja:"段階の数を言う"},{hi:"पहले, फिर",rom:"pahle, phir",ja:"順に説明する"},{hi:"आख़िर में",rom:"ākhir meṁ",ja:"最後の段階"},{hi:"क्या यह ठीक है?",rom:"kyā yah ṭhīk hai?",ja:"確認して本題へ"}],
  phrases:[
   {hi:"मैं पहले काम का तरीक़ा बताता हूँ।",rom:"maiṁ pahle kām kā tarīqā batātā hūṁ.",ja:"まず、仕事の進め方をご説明します。",note:"商談の冒頭で流れを示す一言。"},
   {hi:"इसमें चार क़दम हैं।",rom:"ismeṁ chār qadam haiṁ.",ja:"段階は4つです。",note:"数を先に言うと、聞き手が準備できる。"},
   {hi:"पहले हम ऑनलाइन मिलकर बात करेंगे।",rom:"pahle ham onlāin milkar bāt kareṁge.",ja:"まず、オンラインでお会いして話します。",note:"मिलना → मिलकर（会って）。"},
   {hi:"फिर मैं भारत आकर आपका होटल देखूँगा।",rom:"phir maiṁ Bhārat ākar āpkā hoṭal dekhūṁgā.",ja:"それから、インドに来て、ホテルを拝見します。",note:"आना → आकर（来てから）。"},
   {hi:"आपकी टीम से बात करके मैं एक छोटा प्लान बनाऊँगा।",rom:"āpkī ṭīm se bāt karke maiṁ ek chhoṭā plān banāūṁgā.",ja:"チームの皆さんと話してから、小さな計画を作ります。",note:"करना だけは करके になる。"},
   {hi:"उसके बाद हम साथ में ट्रेनिंग करेंगे।",rom:"uske bād ham sāth meṁ ṭrening kareṁge.",ja:"そのあと、一緒に研修をします。",note:"उसके बाद＝そのあと。"},
   {hi:"आख़िर में हम मिलकर नतीजा देखेंगे।",rom:"ākhir meṁ ham milkar natījā dekheṁge.",ja:"最後に、一緒に結果を確かめます。",note:"मिलकर は「一緒に」の意味でもよく使う。"},
   {hi:"हर क़दम के बाद मैं आपसे पूछूँगा।",rom:"har qadam ke bād maiṁ āpse pūchhūṁgā.",ja:"段階ごとに、ご意見をうかがいます。",note:"相手の考えを大切にしていることを伝える。"},
   {hi:"क्या यह ठीक है?",rom:"kyā yah ṭhīk hai?",ja:"この流れでよろしいですか。",note:"説明のあと、必ず相手に確かめる。"},
   {hi:"अब मैं इंग्लिश में बात करूँगा।",rom:"ab maiṁ inglish meṁ bāt karūṁgā.",ja:"ここからは英語で話します。",note:"細かい条件の前に英語へ切り替える一言。"}],
  model:{title:"仕事の進め方（商談の冒頭）", time:"1分30秒", note:"段取りは練習用の例です。実際の進め方に入れかえましょう。",
   lines:[
    {hi:"नमस्ते, शर्मा जी। आज मिलने के लिए धन्यवाद।",rom:"namaste, Sharmā jī. āj milne ke lie dhanyavād.",ja:"シャルマさん、こんにちは。今日はお会いいただき、ありがとうございます。"},
    {hi:"मैं पहले काम का तरीक़ा बताता हूँ।",rom:"maiṁ pahle kām kā tarīqā batātā hūṁ.",ja:"まず、仕事の進め方をご説明します。"},
    {hi:"इसमें चार क़दम हैं।",rom:"ismeṁ chār qadam haiṁ.",ja:"段階は4つです。"},
    {hi:"पहले हम ऑनलाइन मिलकर बात करेंगे। मैं आपके मेहमानों के बारे में सुनूँगा।",rom:"pahle ham onlāin milkar bāt kareṁge. maiṁ āpke mehmānoṁ ke bāre meṁ sunūṁgā.",ja:"まず、オンラインでお会いして話します。お客様について、お話をうかがいます。"},
    {hi:"फिर मैं भारत आकर आपका होटल देखूँगा।",rom:"phir maiṁ Bhārat ākar āpkā hoṭal dekhūṁgā.",ja:"それから、インドに来て、ホテルを拝見します。"},
    {hi:"आपकी टीम से बात करके मैं एक छोटा प्लान बनाऊँगा।",rom:"āpkī ṭīm se bāt karke maiṁ ek chhoṭā plān banāūṁgā.",ja:"チームの皆さんと話してから、小さな計画を作ります。"},
    {hi:"उसके बाद हम साथ में ट्रेनिंग करेंगे। ट्रेनिंग छोटी और आसान होगी।",rom:"uske bād ham sāth meṁ ṭrening kareṁge. ṭrening chhoṭī aur āsān hogī.",ja:"そのあと、一緒に研修をします。研修は短く、やさしいものです。"},
    {hi:"आख़िर में हम मिलकर नतीजा देखेंगे, और अगला क़दम सोचेंगे।",rom:"ākhir meṁ ham milkar natījā dekheṁge, aur aglā qadam socheṁge.",ja:"最後に、一緒に結果を確かめて、次の一歩を考えます。"},
    {hi:"हर क़दम के बाद मैं आपसे पूछूँगा।",rom:"har qadam ke bād maiṁ āpse pūchhūṁgā.",ja:"段階ごとに、ご意見をうかがいます。"},
    {hi:"क्या यह ठीक है?",rom:"kyā yah ṭhīk hai?",ja:"この流れでよろしいですか。"},
    {hi:"अब मैं इंग्लिश में बात करूँगा। फ़ीस और तारीख़ें इंग्लिश में बताऊँगा।",rom:"ab maiṁ inglish meṁ bāt karūṁgā. fīs aur tārīkheṁ inglish meṁ batāūṁgā.",ja:"ここからは英語で話します。料金と日程は英語でご説明します。"}]},
  task:"自分の仕事の段取りを、-कर を3つ以上と順番の言葉（पहले・फिर・उसके बाद・आख़िर में）を使って1分30秒で説明する。聞き手はインドの取引先（商談の冒頭）。最後に क्या यह ठीक है? と確かめ、英語に切り替える一言を言う。",
  taskEn:"In one and a half minutes, explain the steps of your work at the start of a business meeting in India. Use the -kar form at least three times and the order words pahle, phir, uske bād and ākhir meṁ. Finish by checking that the plan is fine and saying that you will switch to English.",
  qa:[
   {q:"होटल देखने के लिए आप कब आएँगे?",qRom:"hoṭal dekhne ke lie āp kab āeṁge?",a:"ऑनलाइन बात करके हम तारीख़ तय करेंगे।",aRom:"onlāin bāt karke ham tārīkh tay kareṁge.",ja:"質問：ホテルを見にいつ来られますか？／答え：オンラインで話してから、日にちを決めましょう。"},
   {q:"ट्रेनिंग कितनी लंबी होगी?",qRom:"ṭrening kitnī lambī hogī?",a:"यह आपकी टीम पर है। मैं प्लान में बताऊँगा।",aRom:"yah āpkī ṭīm par hai. maiṁ plān meṁ batāūṁgā.",ja:"質問：研修はどのくらいの長さですか？／答え：チームの皆さん次第です。計画の中でお伝えします。"}],
  check:["-कर で2つの動作をつなげられたか（करना は करके）","最初に段階の数を言い、順番の言葉を文の頭に置いたか","段階ごとに相手の意見を聞くと伝えたか","最後に क्या यह ठीक है? と確かめ、英語に切り替える一言を言えたか","1分30秒におさまったか"],
  slide:"4つの段を階段の形に並べ、それぞれに1語（ऑनलाइन・होटल・ट्रेनिंग・नतीजा）だけを書きます。"}
]);

